module SYSTEM(
	clk,
	rst,
	uart_rx_from_heart,
	uart_rx_ai,
	uart_rx_bluetooth,
	uart_rx_camera,
	Echo_left,
	Echo_right,
	Echo_leftfront,
	Echo_rightfront,
	a1,
	a2,
	b1,
	b2,
	c1,
	c2,
	d1,
	d2,
	uart_tx_to_heart,
	uart_tx_to_ai,
	Light_SCL,
	OLED_SCL,
	arm_uart,
	tcon,
	trig_left,
	trig_right,
	trig_leftfront,
	trig_rightfront,
	Light_SDA,
	OLED_SDA,
	dht11);

	//---Ports declearation: generated by Robei---
	input clk;
	input rst;
	input uart_rx_from_heart;
	input uart_rx_ai;
	input uart_rx_bluetooth;
	input uart_rx_camera;
	input Echo_left;
	input Echo_right;
	input Echo_leftfront;
	input Echo_rightfront;
	output a1;
	output a2;
	output b1;
	output b2;
	output c1;
	output c2;
	output d1;
	output d2;
	output uart_tx_to_heart;
	output uart_tx_to_ai;
	output Light_SCL;
	output OLED_SCL;
	output arm_uart;
	output tcon;
	output trig_left;
	output trig_right;
	output trig_leftfront;
	output trig_rightfront;
	inout Light_SDA;
	inout OLED_SDA;
	inout dht11;

	wire clk;
	wire rst;
	wire uart_rx_from_heart;
	wire uart_rx_ai;
	wire uart_rx_bluetooth;
	wire uart_rx_camera;
	wire Echo_left;
	wire Echo_right;
	wire Echo_leftfront;
	wire Echo_rightfront;
	wire a1;
	wire a2;
	wire b1;
	wire b2;
	wire c1;
	wire c2;
	wire d1;
	wire d2;
	wire uart_tx_to_heart;
	wire uart_tx_to_ai;
	wire Light_SCL;
	wire OLED_SCL;
	wire arm_uart;
	wire tcon;
	wire trig_left;
	wire trig_right;
	wire trig_leftfront;
	wire trig_rightfront;
	wire Light_SDA;
	wire OLED_SDA;
	wire dht11;

	//----Code starts here: integrated by Robei-----
	/////////////////////////////////////////////////////////////
	//flag
	    reg            tx_go_to_ai;//语音模块的传输使能
	    wire           ai_tx_done_flag;//语音模块传输完一次数据的标志位
	    wire           rx_flag_ai;//语音模块收到数据的标志位    
	    wire           rx_flag_bluetooth;//蓝牙收到数据的标志位
	    reg            rx_sig_d1;
	    reg            rx_sig_d2;
	    reg            rx_sig_bt1;
	    reg            rx_sig_bt2;
	    wire           dht11_done;
	    wire           light_done;
	    reg            new_cmd_flag;
	    wire    [9:0]  distance_leftfront;
	    wire    [9:0]  distance_rightfront;
	    wire    [9:0]  distance_left;
	    wire    [9:0]  distance_right;
	////////////////////////////////////////////////////////////
	//data
	    reg     [7:0]   num_of_ai;//发给语音模块的序号数据
	    wire    [31:0]  orign_dht;//温湿度原始数据 31到24位为湿度 15到8位为温度
	    wire    [7:0]   spo_data;//血氧数据
	    wire    [7:0]   heart_data;//心率数据
	    reg     [7:0]   data_to_ai;//最终发给语音模块的数据
	    wire    [7:0]   cmd_from_ai;//收到语音助手的命令数据
	    wire    [7:0]   cmd_from_bluetooth;
	    wire    [7:0]   data_tempL;
	    wire    [7:0]   data_tempH;
	    wire    [7:0]   data_humidityL;
	    wire    [7:0]   data_humidityH;
	
	    reg     [3:0]   arm_cmd;
	    wire            arm_uart;
	    wire            tcon;
	    wire    [63:0]  camera_err_out;
	    wire    [19:0]  duty_err;
	    
	    assign duty_err [19:0] = camera_err_out [19:0];
	///////////////////////////////////////////////////////////
	//PWMofWheel
	    reg     [19:0]  duty_a1;
	    reg     [19:0]  duty_a2;
	    reg     [19:0]  duty_b1;
	    reg     [19:0]  duty_b2;
	    reg     [19:0]  duty_c1;
	    reg     [19:0]  duty_c2;
	    reg     [19:0]  duty_d1;
	    reg     [19:0]  duty_d2;  
	/////////////////////////////////////////////////////////// 
	    reg     [15:0]  data_angle1 = 16'd500;
	    reg     [15:0]  data_angle2 = 16'd500;
	    reg     [15:0]  data_angle3 = 16'd625;
	    reg     [15:0]  data_angle4 = 16'd500;
	    reg     [15:0]  data_angle5 = 16'd500;
	    reg     [15:0]  data_angle6 = 16'd500;
	//////////////////////////////////////////////////////////
	    parameter      IDLE_1     =  8'd50,
	                    IDLE_CAR   =  8'd52,
	                    IDLE_SENSOR=  8'd56,
	                    
	                    AUTO_PILOT =  8'd58,
	                    AUTO_STRAIGHT=8'd60,
	                    AUTO_LEFT  =  8'd62,
	                    AUTO_RIGHT =  8'd63, 
	                    CAMERA_WITH_ULTRASONIC = 8'd69,  
	        
	                    SPEED_DUTY =  20'd500000,
	                    AUTO_SPEED =  20'd200000,
	                    FORWARD    =  8'd9,
	                    BACKWARD   =  8'd10,
	                    LEFT       =  8'd11,
	                    RIGHT      =  8'd12,
	                    CLOCKWISE  =  8'd13,
	                    ATCLOCK    =  8'd14,
	                  
	                    RST_POS    =  8'd27,
	                    ARM_1      =  8'd15,
		                ARM_2      =  8'd16,
		                ARM_3      =  8'd17,
		                ARM_4      =  8'd18,
		                ARM_5      =  8'd19,
		                ARM_6      =  8'd20,
		                DARM_1     =  8'd21, 
		                DARM_2     =  8'd22,
		                DARM_3     =  8'd23,
		                DARM_4     =  8'd24,
		                DARM_5     =  8'd25,
	                    DARM_6     =  8'd26,
	                   
	                    ASK_TEMP   =  8'd5,
	                    ASK_HUMI   =  8'd6,
	                    ASK_SPO    =  8'd7,
	                    ASK_HEART  =  8'd8;
	                    
	              
	    parameter	    T_40MS     =  31'd4000000,//1s16666666
	                    T_6S       =    'd10_000_000,
		                T_Delay1   =    'd5_000_000,
		                T_Delay2   =    'd2,
		                T_DAC1S    =    'd33333333;
	    //cnt                                       
	    reg     [39:0]  cnt;
	    reg     [39:0]  cnt2;
	    
	    //state machine
	    reg     [7:0]   cur_a_state;
		reg     [7:0]   next_a_state;
		reg     [7:0]   cur_sensor_state;
		reg     [7:0]   next_sensor_state;
		reg     [7:0]   cur_car_state;
		reg     [7:0]   next_car_state;
		reg     [7:0]   auto_pilot_state;
		reg     [7:0]   next_AP_state;
	
	//收到语音模块数据的标志位     
	     always @(posedge clk or negedge rst)begin
	        if(!rst) begin
	            rx_sig_d1 <= 1'd0;
	            rx_sig_d2 <= 1'd0;
	        end
	        else begin
	            rx_sig_d1 <= rx_flag_ai;
	            rx_sig_d2 <= rx_sig_d1;
	        end
	     end
	     
	     assign rx_sig_rise = ~rx_sig_d2 && rx_sig_d1;//数据送到标志 
	//收到蓝牙数据的标志位
	always @(posedge clk or negedge rst)begin
		 	if(!rst) begin
		 		rx_sig_bt1 <= 1'd0;
		 		rx_sig_bt2 <= 1'd0;
		 	end
		 	else begin
		 		rx_sig_bt1 <= rx_flag_bluetooth;
		 		rx_sig_bt2 <= rx_sig_bt1;
		 	end
		 end
		 
		 assign rx_bt_rise = ~rx_sig_bt2 && rx_sig_bt1;//蓝牙数据送到标志
	////////////////////////////////////////////////////////////
	//多感知全场景智能领航状态机
	always @(posedge clk or negedge rst)begin
		 	if(!rst)
		 		cur_car_state <= IDLE_CAR;
		 	else
		 		cur_car_state <= next_car_state;
		 end
	 always @(posedge clk or negedge rst)begin
	        if(!rst)
	            auto_pilot_state <= CAMERA_WITH_ULTRASONIC;//改
	        else
	            auto_pilot_state <= next_AP_state;
	 end
		 
		 always @(*)begin
	
		 next_AP_state = AUTO_STRAIGHT;
		           case(cur_car_state)//T2
		               IDLE_CAR        :begin
		            
		                   if(rx_bt_rise && cmd_from_bluetooth == 8'h13 )
		                       next_car_state = FORWARD;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h11 )
		                       next_car_state = BACKWARD;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h10 )
		                       next_car_state = LEFT;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h0d )
		                       next_car_state = RIGHT;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h0c )
		                       next_car_state = CLOCKWISE;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h0a )
		                       next_car_state = ATCLOCK; 
		                   else if(rx_sig_rise && cmd_from_ai == 8'h11 )
		                       next_car_state = AUTO_PILOT;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h66 )
		                       next_car_state = AUTO_PILOT;            
		                   else
		                       next_car_state = IDLE_CAR;
		               end
		               FORWARD       :begin
		              //auto_pilot_state = CAMERA_WITH_ULTRASONIC;
		               //next_AP_state = CAMERA_WITH_ULTRASONIC;
		                   if(cnt2 >= T_Delay1)
		                       next_car_state = IDLE_CAR;
		                   else
		                       next_car_state = FORWARD;
		               end
		               BACKWARD       :begin
		              
		               next_AP_state = CAMERA_WITH_ULTRASONIC;
	                       if(cnt2 >= T_Delay1)
		                       next_car_state = IDLE_CAR;
		                   else
		                       next_car_state = BACKWARD;
		               end
		               LEFT       :begin
		              // next_car_state = IDLE_CAR;
		              //auto_pilot_state = CAMERA_WITH_ULTRASONIC;
		              // next_AP_state = CAMERA_WITH_ULTRASONIC;
		                  if(cnt2 >= T_Delay1)
		                       next_car_state = IDLE_CAR;
		                   else
		                       next_car_state = LEFT;
		               end
		               RIGHT       :begin
		               //next_car_state = IDLE_CAR;
		              // auto_pilot_state = CAMERA_WITH_ULTRASONIC;
		              // next_AP_state = CAMERA_WITH_ULTRASONIC;
		                   if(cnt2 >= T_Delay1)
		                       next_car_state = IDLE_CAR;
		                   else
		                       next_car_state = RIGHT;
		               end
		               CLOCKWISE       :begin
		             //  next_car_state = IDLE_CAR;
		               //auto_pilot_state = CAMERA_WITH_ULTRASONIC;
		              // next_AP_state = CAMERA_WITH_ULTRASONIC;
		                   if(cnt2 >= T_Delay1)
		                       next_car_state = IDLE_CAR;
		                   else
		                       next_car_state = CLOCKWISE;
		               end
		               ATCLOCK       :begin
		              // next_car_state = IDLE_CAR;
		              // auto_pilot_state = CAMERA_WITH_ULTRASONIC;
		              // next_AP_state = CAMERA_WITH_ULTRASONIC;
		                   if(cnt2 >= T_Delay1)
		                       next_car_state = IDLE_CAR;
		                   else
		                       next_car_state = ATCLOCK;
		               end
		               /////////////////////////////////////////////
		               //AP:全场景视觉光线自适应融合超声波自主导盲导航算法
		               AUTO_PILOT       :begin
	                       case(auto_pilot_state)
	                       CAMERA_WITH_ULTRASONIC:  begin
	                           if(light_data <= 'd30)//当光线不足以支持摄像头算法时
	                               next_AP_state = AUTO_STRAIGHT;//进入到纯超声波算法
	                           else if(distance_rightfront <= 'd25 || distance_leftfront <= 'd25)//当遇到障碍物时进入纯超声波算法以优化芯片算力
	                               next_AP_state = AUTO_STRAIGHT;
	                           else 
	                               next_AP_state = CAMERA_WITH_ULTRASONIC;
	                       end
	                       AUTO_STRAIGHT:    begin
	                           if(distance_leftfront <= 'd25)
	                               next_AP_state = AUTO_RIGHT;
	                           else if(distance_rightfront <= 'd25)
	                               next_AP_state = AUTO_LEFT;    
	                           else if(rx_sig_rise && cmd_from_ai == 8'h12)
	                               next_car_state = IDLE_CAR;
	                           else
	                               next_AP_state = AUTO_STRAIGHT;
	                       end
	                       AUTO_LEFT:    begin
	                           if(distance_leftfront >= 'd25 && distance_rightfront >= 'd25)
	                               next_AP_state = CAMERA_WITH_ULTRASONIC;
	                           else if(distance_left <= 'd25)
	                               next_AP_state = AUTO_RIGHT;    
	                           else if(rx_sig_rise && cmd_from_ai == 8'h12)
	                               next_car_state = IDLE_CAR;
	                           else
	                               next_AP_state = AUTO_LEFT;
	                       end
	                       AUTO_RIGHT:    begin
	                           if(distance_leftfront >= 'd25 && distance_rightfront >= 'd25)
	                               next_AP_state = CAMERA_WITH_ULTRASONIC;
	                           else if(distance_right <= 'd25)
	                               next_AP_state = AUTO_LEFT;    
	                           else if(rx_sig_rise && cmd_from_ai == 8'h12)
	                               next_car_state = IDLE_CAR;
	                           else
	                               next_AP_state = AUTO_RIGHT;
	                       end
	                       endcase
	                   end
	                   ///////////////////////////////////////////////
		               default:
		               begin
		               next_car_state = IDLE_CAR;
		               next_AP_state  = CAMERA_WITH_ULTRASONIC;
		               end
		           endcase
		       end
		       	 
		 always @(posedge clk or negedge rst) begin
		       if(!rst) begin
		           duty_a1 <= 20'd000000;
		           duty_a2 <= 20'd000000;
		           duty_b1 <= 20'd000000;
		           duty_b2 <= 20'd000000;
		           duty_c1 <= 20'd000000;
		           duty_c2 <= 20'd000000;
		           duty_d1 <= 20'd000000;
		           duty_d2 <= 20'd000000;
		           cnt2 <= 'd0;
		       end
		       else begin
	               case(cur_car_state)
	                   FORWARD     :begin
	                       if(cnt2 >= T_Delay1)
	                       begin
		                       cnt2 <= 'd0;
		                   end
		                   else
		                   begin
		                       cnt2 <= cnt2 + 1'b1;
		                   end
	                       duty_a1 <= SPEED_DUTY;
	                       duty_a2 <= 20'd000000;
	                       duty_b1 <= SPEED_DUTY;
	                       duty_b2 <= 20'd000000;
	                       duty_c1 <= SPEED_DUTY;
	                       duty_c2 <= 20'd000000;
	                       duty_d1 <= SPEED_DUTY;
	                       duty_d2 <= 20'd000000;
	                   end
	                   BACKWARD     :begin
	                       if(cnt2 >= T_Delay1)
	                       begin
		                       cnt2 <= 'd0;
		                   end
		                   else
		                   begin
		                       cnt2 <= cnt2 + 1'b1;
		                   end
	                       duty_a1 <= 20'd000000;
	                       duty_a2 <= SPEED_DUTY;
	                       duty_b1 <= 20'd000000;
	                       duty_b2 <= SPEED_DUTY;
	                       duty_c1 <= 20'd000000;
	                       duty_c2 <= SPEED_DUTY;
	                       duty_d1 <= 20'd000000;
	                       duty_d2 <= SPEED_DUTY;
	                   end
	                   LEFT     :begin
	                       if(cnt2 >= T_Delay1)
	                       begin
		                       cnt2 <= 'd0;
		                   end
		                   else
		                   begin
		                       cnt2 <= cnt2 + 1'b1;
		                   end
	                       duty_a1 <= SPEED_DUTY;
	                       duty_a2 <= 20'd000000;
	                       duty_b1 <= 20'd000000;
	                       duty_b2 <= SPEED_DUTY;
	                       duty_c1 <= 20'd000000;
	                       duty_c2 <= SPEED_DUTY;
	                       duty_d1 <= SPEED_DUTY;
	                       duty_d2 <= 20'd000000;
	                   end
	                   RIGHT     :begin
	                       if(cnt2 >= T_Delay1)
	                       begin
		                       cnt2 <= 'd0;
		                   end
		                   else
		                   begin
		                       cnt2 <= cnt2 + 1'b1;
		                   end
	                       duty_a1 <= 20'd000000;
	                       duty_a2 <= SPEED_DUTY;
	                       duty_b1 <= SPEED_DUTY;
	                       duty_b2 <= 20'd000000;
	                       duty_c1 <= SPEED_DUTY;
	                       duty_c2 <= 20'd000000;
	                       duty_d1 <= 20'd000000;
	                       duty_d2 <= SPEED_DUTY;
	                   end
	                   CLOCKWISE     :begin
	                       if(cnt2 >= T_Delay1)
	                       begin
		                       cnt2 <= 'd0;
		                   end
		                   else
		                   begin
		                       cnt2 <= cnt2 + 1'b1;
		                   end
	                       duty_a1 <= SPEED_DUTY;
	                       duty_a2 <= 20'd000000;
	                       duty_b1 <= SPEED_DUTY;
	                       duty_b2 <= 20'd000000;
	                       duty_c1 <= 20'd000000;
	                       duty_c2 <= SPEED_DUTY;
	                       duty_d1 <= 20'd000000;
	                       duty_d2 <= SPEED_DUTY;
	                   end
	                   ATCLOCK     :begin
	                       if(cnt2 >= T_Delay1)
	                       begin
		                       cnt2 <= 'd0;
		                   end
		                   else
		                   begin
		                       cnt2 <= cnt2 + 1'b1;
		                   end
	                       duty_a1 <= 20'd000000;
	                       duty_a2 <= SPEED_DUTY;
	                       duty_b1 <= 20'd000000;
	                       duty_b2 <= SPEED_DUTY;
	                       duty_c1 <= SPEED_DUTY;
	                       duty_c2 <= 20'd000000;
	                       duty_d1 <= SPEED_DUTY;
	                       duty_d2 <= 20'd000000;
	                   end
	                   AUTO_PILOT  :begin
	                       case(auto_pilot_state)
	                       CAMERA_WITH_ULTRASONIC:    begin
	                           duty_a1 <= AUTO_SPEED + duty_err;
	                           duty_a2 <= 20'd000000;
	                           duty_b1 <= AUTO_SPEED + duty_err;
	                           duty_b2 <= 20'd000000;
	                           duty_c1 <= AUTO_SPEED - duty_err;
	                           duty_c2 <= 20'd000000;
	                           duty_d1 <= AUTO_SPEED - duty_err;
	                           duty_d2 <= 20'd000000;
	                       end
	                       AUTO_STRAIGHT:    begin
	                           duty_a1 <= AUTO_SPEED;
	                           duty_a2 <= 20'd000000;
	                           duty_b1 <= AUTO_SPEED;
	                           duty_b2 <= 20'd000000;
	                           duty_c1 <= AUTO_SPEED;
	                           duty_c2 <= 20'd000000;
	                           duty_d1 <= AUTO_SPEED;
	                           duty_d2 <= 20'd000000;
	                       end
	                       AUTO_LEFT:    begin
	                           duty_a1 <= AUTO_SPEED;
	                           duty_a2 <= 20'd000000;
	                           duty_b1 <= 20'd000000;
	                           duty_b2 <= AUTO_SPEED;
	                           duty_c1 <= 20'd000000;
	                           duty_c2 <= AUTO_SPEED;
	                           duty_d1 <= AUTO_SPEED;
	                           duty_d2 <= 20'd000000;
	                       end
	                       AUTO_RIGHT:    begin
	                           duty_a1 <= 20'd000000;
	                           duty_a2 <= AUTO_SPEED;
	                           duty_b1 <= AUTO_SPEED;
	                           duty_b2 <= 20'd000000;
	                           duty_c1 <= AUTO_SPEED;
	                           duty_c2 <= 20'd000000;
	                           duty_d1 <= 20'd000000;
	                           duty_d2 <= AUTO_SPEED;
	                       end 
	                       endcase
	                   end
	                   IDLE_CAR    :begin
	                       duty_a1 <= 20'd000000;
	                       duty_a2 <= 20'd000000;
	                       duty_b1 <= 20'd000000;
	                       duty_b2 <= 20'd000000;
	                       duty_c1 <= 20'd000000;
	                       duty_c2 <= 20'd000000;
	                       duty_d1 <= 20'd000000;
	                       duty_d2 <= 20'd000000;
	                   end
	                   default:;
	                   endcase
	               end
		 end
	////////////////////////////////////////////////////////////
	//领航牵引机械臂状态机
	always @(posedge clk or negedge rst)begin
		 	if(!rst)
		 		cur_a_state <= IDLE_1;
		 	else
		 		cur_a_state <= next_a_state;
		 end
		 
		 always @(*)begin
		 next_a_state = IDLE_1;//空闲状态
		           case(cur_a_state)
		               IDLE_1        :begin
		                   if(rx_bt_rise && cmd_from_bluetooth == 8'h33)
		                       next_a_state = RST_POS;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'hcc)
		                       next_a_state = ARM_6;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h03)
		                       next_a_state = ARM_5;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h05)
		                       next_a_state = ARM_4;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h09)
		                       next_a_state = ARM_3;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h07)
		                       next_a_state = ARM_2;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h0b)
		                       next_a_state = ARM_1;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'hdd)
		                       next_a_state = DARM_6;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h04)
		                       next_a_state = DARM_5;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h06)
		                       next_a_state = DARM_4;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'hbc)
		                       next_a_state = DARM_3;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'h08)
		                       next_a_state = DARM_2;
		                   else if(rx_bt_rise && cmd_from_bluetooth == 8'hac)
		                       next_a_state = DARM_1;
		                   else
		                       next_a_state = IDLE_1;
		               end
		               RST_POS       :begin
		                   if(cnt >= T_40MS)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = RST_POS;
		               end
		               ARM_6       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = ARM_6;
		               end
		               ARM_5       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = ARM_5;
		               end
		               ARM_4       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = ARM_4;
		               end
		               ARM_3       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = ARM_3;
		               end
		               ARM_2       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = ARM_2;
		               end
		               ARM_1       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = ARM_1;
		               end
		               DARM_6       :begin
		                   if(cnt >= T_Delay2)
		                       next_a_state = IDLE_1;
		                   else
		                       next_a_state = DARM_6;
		               end
		               DARM_5       :begin
		                   if(cnt >= T_Delay2)
