	                       end
	                   ARM_6     :begin
	                       if(cnt >= T_Delay2) begin
	                           cnt <= 'd0;
	                       end
	                       else begin
	                           cnt <= cnt + 1'b1;
	                       end
	                       if(data_angle6 < 'd980 && data_angle6 > 'd0)begin
	                           data_angle6 <= data_angle6 + 'd2;
	                           new_cmd_flag <= 1'b1;
	                       end
	                       else begin
	                           data_angle6 <= data_angle6;
	                           new_cmd_flag <= 1'b0;
	                       end
	                   end
	                   ARM_5     :begin
	                       if(cnt >= T_Delay2) begin
	                           cnt <= 'd0;
	                       end
	                       else begin
	                           cnt <= cnt + 1'b1;
	                       end
	                       if(data_angle5 < 'd980 && data_angle5 > 'd0)begin
