	                   DARM_6     :begin
	                       if(cnt >= T_Delay2) begin
	                           cnt <= 'd0;
	                       end
	                       else begin
	                           cnt <= cnt + 1'b1;
	                       end
	                       if(data_angle6 <= 'd1000 && data_angle6 >= 'd50)begin
	                           data_angle6 <= data_angle6 - 'd2;
	                           new_cmd_flag <= 1'b1;
	                       end
	                       else begin
	                           data_angle6 <= data_angle6;
	                           new_cmd_flag <= 1'b0;
	                       end
	                   end
	                   DARM_5     :begin
