	////////////////////////////////////////////////////////////
	//AI引擎大脑状态机
	    always @(posedge clk or negedge rst)begin
	         if(!rst)
	             cur_sensor_state <= IDLE_SENSOR;
	         else
	             cur_sensor_state <= next_sensor_state;
	         end
	         
	         always @(*)begin
	         next_sensor_state = IDLE_SENSOR;
	                   case(cur_sensor_state)//T2
	                       IDLE_SENSOR        :begin
	                           if(rx_sig_rise && cmd_from_ai == 8'h05 )
	                               next_sensor_state = ASK_TEMP;
	                           else if(rx_sig_rise && cmd_from_ai == 8'h06 )
	                               next_sensor_state = ASK_HUMI;
	                           else if(rx_sig_rise && cmd_from_ai == 8'h07 )
	                               next_sensor_state = ASK_SPO;  
	                           else if(rx_sig_rise && cmd_from_ai == 8'h08 )
	                               next_sensor_state = ASK_HEART;  
	                           else
	                               next_sensor_state = IDLE_SENSOR;
	                       end
	                       ASK_TEMP       :begin
	                           if(rx_sig_rise && cmd_from_ai == 8'h21 )
	                                next_sensor_state = IDLE_SENSOR;
	                           else if(ai_tx_done_flag == 1'b1)
	                                next_sensor_state = IDLE_SENSOR;
	                           else next_sensor_state = ASK_TEMP;
	                       end               
	                       ASK_HUMI       :begin
	                           if(rx_sig_rise && cmd_from_ai == 8'h21 )
	                                next_sensor_state = IDLE_SENSOR;
	                           else if(ai_tx_done_flag == 1'b1)
	                                next_sensor_state = IDLE_SENSOR;
	                           else next_sensor_state = ASK_HUMI;
	                       end
	                       ASK_SPO       :begin
	                           if(rx_sig_rise && cmd_from_ai == 8'h21 )
	                                next_sensor_state = IDLE_SENSOR;
	                           else if(ai_tx_done_flag == 1'b1)
	                                next_sensor_state = IDLE_SENSOR;
	                           else next_sensor_state = ASK_SPO;
	                       end
	                       ASK_HEART       :begin
	                           if(rx_sig_rise && cmd_from_ai == 8'h21 )
	                                next_sensor_state = IDLE_SENSOR;
	                           else if(ai_tx_done_flag == 1'b1)
	                                next_sensor_state = IDLE_SENSOR;
	                           else next_sensor_state = ASK_HEART;
	                       end	      
	                   endcase
	               end	       
		       
		 always @(posedge clk or negedge rst) begin
		     if(!rst) begin
		         tx_go_to_ai <= 1'b0;
		     end
		     else
		         case(cur_sensor_state)
		             ASK_TEMP    :begin
		                 tx_go_to_ai <= 1'b1;
		                 data_to_ai[7:0] <= orign_dht[15:8]; 
		                 num_of_ai <= 8'h01;
		             end
		             ASK_HUMI    :begin
		                 tx_go_to_ai <= 1'b1; 
		                 data_to_ai[7:0] <= orign_dht[31:24];
		                 num_of_ai <= 8'h02;
		             end
		             ASK_SPO    :begin
		                 tx_go_to_ai <= 1'b1;
		                 data_to_ai <= spo_data; 
		                 num_of_ai <= 8'h03;
		             end
		             ASK_HEART    :begin
		                 tx_go_to_ai <= 1'b1;
		                 data_to_ai <= heart_data; 
		                 num_of_ai <= 8'h04;
		             end
		             IDLE_SENSOR     :begin
		                 tx_go_to_ai <= 1'b0;
		             end
		         endcase
		 end
